{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Lambda permission lacks SourceArn or SourceAccount restriction",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "MEDIUM",
      "explanation": "The Lambda permission allows invocation by the 'apigateway.amazonaws.com' principal without restricting it to a specific API Gateway ARN (SourceArn) or account (SourceAccount). This permits any API Gateway in any AWS account to invoke this function, potentially leading to unauthorized access or abuse."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn    = \"${aws_apigatewayv2_api.my_api.execution_arn}/*/*\"\n}",
  "fix_summary": "Added the `source_arn` argument to restrict the Lambda permission to invocations from a specific API Gateway. Note: The variable `aws_apigatewayv2_api.my_api.execution_arn` is used as a placeholder for the actual API Gateway resource reference; you must replace this with the correct ARN of your API Gateway stage/resource."
}
